import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.DCKC-kU_.js";const l=JSON.parse('{"title":"Normative schemas","description":"","frontmatter":{},"headers":[],"relativePath":"spec/schemas/index.md","filePath":"spec/schemas/index.md"}'),s={name:"spec/schemas/index.md"};function c(i,e,n,d,h,m){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="normative-schemas" tabindex="-1">Normative schemas <a class="header-anchor" href="#normative-schemas" aria-label="Permalink to &quot;Normative schemas&quot;">​</a></h1><p>These are the normative structural minima of the Takoform specification. Schema validity is necessary but not sufficient: the semantic verifier rules in the owning Form Definition, Form Package, Interface, and trust contracts are also normative and may reject a structurally valid document. Where prose and a schema directly disagree about the same structural condition, the schema wins.</p><table tabindex="0"><thead><tr><th>Schema</th><th>Contract</th></tr></thead><tbody><tr><td><a href="form-ref.schema.json"><code>form-ref.schema.json</code></a></td><td>the frozen v1alpha1 four-field immutable Form reference</td></tr><tr><td><a href="form-ref-v1alpha2.schema.json"><code>form-ref-v1alpha2.schema.json</code></a></td><td>the current v1alpha2 four-field immutable Form reference</td></tr><tr><td><a href="form-definition.schema.json"><code>form-definition.schema.json</code></a></td><td>the frozen v1alpha1 data-only Form Definition</td></tr><tr><td><a href="form-definition-v1alpha2.schema.json"><code>form-definition-v1alpha2.schema.json</code></a></td><td>the current v1alpha2 data-only Form Definition</td></tr><tr><td><a href="package-index.schema.json"><code>package-index.schema.json</code></a></td><td>the closed Form Package inventory and its identity</td></tr><tr><td><a href="package-index-v1alpha2.schema.json"><code>package-index-v1alpha2.schema.json</code></a></td><td>the retained content-addressed package profile for v1alpha1 FormRefs</td></tr><tr><td><a href="package-index-v1alpha3.schema.json"><code>package-index-v1alpha3.schema.json</code></a></td><td>the current content-addressed package profile for v1alpha2 FormRefs</td></tr><tr><td><a href="form-package-revocation.schema.json"><code>form-package-revocation.schema.json</code></a></td><td>one append-only revocation statement</td></tr><tr><td><a href="form-package-revocation-checkpoint.schema.json"><code>form-package-revocation-checkpoint.schema.json</code></a></td><td>the cumulative, hash-chained revocation checkpoint</td></tr><tr><td><a href="host-discovery.schema.json"><code>host-discovery.schema.json</code></a></td><td>the frozen provider-v1 host discovery document</td></tr><tr><td><a href="host-api-wire.schema.json"><code>host-api-wire.schema.json</code></a></td><td>the frozen provider-v1 Resource and Interface wire envelopes</td></tr><tr><td><a href="host-discovery-v1alpha2.schema.json"><code>host-discovery-v1alpha2.schema.json</code></a></td><td>the current provider-v2 host discovery document</td></tr><tr><td><a href="host-api-wire-v1alpha2.schema.json"><code>host-api-wire-v1alpha2.schema.json</code></a></td><td>the current Resource, lifecycle response, Interface projection, and error envelopes</td></tr></tbody></table><p>The Form Package verifier embeds its own copies of the package schemas so it has no filesystem dependency at runtime. The host discovery implementation keeps its published copy under <code>schemas/</code>. The wire-envelope schema is normative and is consumed by host/provider conformance rather than embedded in the data-only package verifier. <code>go test ./spec</code> compiles every schema and proves every implementation copy is byte-identical to its normative source.</p><p>Every schema <code>$id</code> is also a retrieval URL. The files in this directory are the only source; <code>bun run sync:public-schemas</code> projects them byte-for-byte into <code>website/public/schemas/</code>, and <code>bun run check:public-surfaces</code> rejects missing, extra, or drifted public copies. Do not edit the generated public copies.</p><p>Once a <code>$id</code> URL resolves, its bytes are an immutable published identity. <a href="../../release/public-schema-identities.json"><code>release/public-schema-identities.json</code></a> is the append-only ledger of every such identity, its exact digest, normative source, and public projection. The public-surface gate requires the normative set to equal that ledger. Deployment also compares the candidate ledger with every retained ledger version in repository history, so a published identity cannot disappear by deleting both its source and current ledger entry.</p><p>Deployment fetches every retained URL immediately before mutation and refuses to overwrite a differing or unavailable identity. A wholly DNS-absent origin can be minted only through the explicit initial-origin acknowledgement documented in [<code>website/README.md</code>]; that acknowledgement cannot bypass any existing response or mismatch.</p>',7)])])}const f=t(s,[["render",c]]);export{l as __pageData,f as default};
